    [Fact]
    public void Crop_box_matches_the_android_version()
    {
        Vectors.Should().HaveCount(40);
        for (var i = 0; i < Vectors.Length; i++)
        {
            var v = Vectors[i];
            var face = new RectD(v[0], v[1], v[2], v[3]);
            double? headTop = double.IsNaN(v[4]) ? null : v[4];
            var rules = new CropRules { TopGap = v[6], BottomGap = v[7], LeftGap = v[8], RightGap = v[9] };

            var (box, _) = CropGeometry.ComputeBox(face, headTop, v[5], rules);

            box.Left.Should().BeApproximately(v[10], 1e-6, $"örnek {i}");
            box.Top.Should().BeApproximately(v[11], 1e-6, $"örnek {i}");
            box.Width.Should().BeApproximately(v[12], 1e-6, $"örnek {i}");
            box.Height.Should().BeApproximately(v[13], 1e-6, $"örnek {i}");
        }
    }
